-- Standalone: Las Vegas (race 5) predictions, feature importances, actual results + model scores.
-- Predictions were made after the race but from pre-race data only (season form through 10/3,
-- Vegas history 2022-25); results were added only after both models were logged.
-- Safe to re-run; replaces any existing Las Vegas rows.
begin;

update races set status = 'completed', winner = 'Chase Briscoe', blend_note = '60% intermediate season form (5 races + spring Vegas) / 40% Las Vegas history 2022-25' where chase_round = 5;

delete from predictions where race_id = (select id from races where chase_round = 5);
delete from feature_importances where race_id = (select id from races where chase_round = 5);
delete from results where race_id = (select id from races where chase_round = 5);
delete from model_scores where race_id = (select id from races where chase_round = 5);





select (select count(*) from predictions where race_id = (select id from races where chase_round = 5)) as predictions, (select count(*) from results where race_id = (select id from races where chase_round = 5)) as results;

commit;
